/**
 * 协作域事件：task.comment_created / mention.parsed（§8.1 事件目录）。
 */
import type { DomainEventEnvelope } from './envelope';
export declare const COMMENT_EVENTS: {
    readonly CREATED: "task.comment_created";
    readonly MENTION_PARSED: "mention.parsed";
};
export type CommentEventName = (typeof COMMENT_EVENTS)[keyof typeof COMMENT_EVENTS];
/** 被 @ 的用户（仅 id；展示名由消费方经 BC-01 用户只读视图解析） */
export interface MentionedUser {
    userId: string;
}
export interface CommentEventPayloads {
    [COMMENT_EVENTS.CREATED]: DomainEventEnvelope & {
        taskId: string;
        projectId: string;
        commentId: string;
    };
    [COMMENT_EVENTS.MENTION_PARSED]: DomainEventEnvelope & {
        taskId: string;
        commentId: string;
        mentions: MentionedUser[];
    };
}
export type CommentDomainEvent<K extends CommentEventName = CommentEventName> = {
    name: K;
    payload: CommentEventPayloads[K];
};
